Translate("esMX", "gryphon-master-talonaxe", {
	title = "Maestro de grifos Talonaxe",
	subtitle = "Maestro del aviario de Pico Nidal",
	found = "El aviario de Pico Nidal",
	hint = "Suba al aviario de Pico Nidal y hable con su maestro.",
	allegiance = "Clan Martillo Salvaje",
	aliases = { "Talonaxe" },
	sections = {
		{
			title = "Resumen",
			text = [=[El maestro de grifos Talonaxe cuida el gran aviario de {link:aerie-peak}Pico Nidal{/link}. Conoce a cada grifo de las bandadas del clan y a cada jinete que alguna vez montó uno. Recuerda sus nombres mucho después de que los demás los hayan olvidado, y guarda un rincón de cariño para la {link:explorers-league}Liga de Expedicionarios{/link}, pues su propio padre estuvo entre los enanos que descubrieron {link:uldaman}Uldaman{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Los grifos son la fuerza de los Martillo Salvaje, y Talonaxe es su guardián. Cuando se pierde un grifo, todo el clan lo siente. Cuando desapareció el heredero del mejor grifo del aviario, fue Talonaxe quien no descansó hasta encontrar al joven. Su historia muestra lo estrechamente ligada que está la suerte de los enanos a la de sus bestias.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Adiestra a los grifos de {link:aerie-peak}Pico Nidal{/link} y les asigna jinetes.
• Prestó una vez a su mejor jinete, {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, al explorador {link:brohann-caskbelly}Brohann Caskbelly{/link} para un vuelo sobre el {link:swamp-of-sorrows}Pantano de las Penas{/link}.
• Prescindió de Rhapsody cuando la bebida se adueñó de él tras aquel vuelo.
• Dirigió la búsqueda de Sharpbeak, desde las jaulas de los {link:witherbark-trolls}Secacorteza{/link} hasta el {link:the-altar-of-zul}Altar de Zul{/link}.
• Recurrió a un adivino Martillo Salvaje de {link:blasted-lands}Las Tierras Devastadas{/link} cuando fracasaron todas las demás búsquedas.]=],
		},
	},
	chapters = {
		{
			title = "El jinete que cayó",
			hint = [=[Sepa por el maestro de grifos qué fue del jinete enviado con Brohann.]=],
			text = [=[Talonaxe recordó el vuelo al instante. Había enviado a su mejor jinete a volar con {link:brohann-caskbelly}Brohann{/link} sobre el pantano en busca de un templo ahogado. El jinete era {link:rhapsody-shindigger}Rhapsody Shindigger{/link}, y nadie en el aviario volaba como él. Pero Rhapsody volvió de aquel vuelo conmocionado y sediento, y su sed no hizo más que crecer. Al final, el maestro del aviario tuvo que despedirlo.]=],
		},
		{
			title = "El heredero perdido",
			hint = [=[Busque a un joven grifo desaparecido en los poblados trols y en el Altar de Zul.]=],
			text = [=[Sharpbeak, heredero del grifo más poderoso del aviario, desapareció mientras cazaba con sus padres. Talonaxe estaba seguro de que se lo habían llevado los trols. Se registraron las jaulas de los poblados {link:witherbark-trolls}Secacorteza{/link} y se hallaron vacías. Después se registró el {link:the-altar-of-zul}Altar de Zul{/link}, donde los Vilrama hacen sus sacrificios. El joven grifo tampoco estaba allí, y Talonaxe no sabía si llorar o alegrarse.]=],
		},
		{
			title = "Una pluma y un adivino",
			hint = [=[Lleve una pluma del nido de Sharpbeak al adivino de Nethergarde.]=],
			text = [=[Con todos los rastros ya fríos, Talonaxe recurrió a {link:thadius-grimshade}Thadius Grimshade{/link}. Grimshade había dejado {link:aerie-peak}Pico Nidal{/link} años atrás para buscar un saber más oscuro, pero Talonaxe aún lo consideraba un Martillo Salvaje de corazón. Se envió a la torre del adivino una pluma del nido donde había dormido el joven grifo, para que pudiera seguir su hilo hasta su dueño.]=],
		},
		{
			title = "La jaula del acantilado",
			hint = "Traiga a casa al joven grifo retenido por los Vilrama.",
			text = [=[La adivinación de {link:thadius-grimshade}Grimshade{/link} encontró a Sharpbeak en una jaula en lo alto de un acantilado de {link:jintha-alor}Jintha'Alor{/link}. La llave colgaba del cinturón de la sacerdotisa vil {link:vile-priestess-hexx}Hexx{/link}. Los Martillo Salvaje no podían soportarlo. La sacerdotisa cayó, la jaula se abrió y Sharpbeak voló a casa con sus padres. Talonaxe los vio mimar a su cría, y los ojos del viejo {link:dwarves}enano{/link} no estaban secos.]=],
		},
	},
	mentions = {
		{ text = "Maestro de grifos Talonaxe" },
		{ text = "{link:rhapsody-shindigger}Rhapsody Shindigger{/link}" },
		{ text = "Jaulas {link:witherbark-trolls}Secacorteza{/link}" },
		{ text = "{link:the-altar-of-zul}El Altar de Zul{/link}" },
		{ text = "{link:thadius-grimshade}Thadius Grimshade{/link}" },
		{
			text = [=[Regreso a {link:the-hinterlands}las Tierras del Interior{/link}]=],
		},
		{ text = "Salvar a Sharpbeak" },
	},
	bonds = {
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "su Alto Thane" },
		{ id = "rhapsody-shindigger", name = "Rhapsody Shindigger", note = "antaño su mejor jinete" },
		{ id = "sharpbeak", name = "Sharpbeak", note = "el heredero perdido del aviario" },
		{ id = "thadius-grimshade", name = "Thadius Grimshade", note = "un Martillo Salvaje de corazón" },
		{ id = "vile-priestess-hexx", name = "Sacerdotisa vil Hexx", note = "tenía la llave de la jaula de Sharpbeak" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "tomó prestado a su mejor jinete" },
	},
})

