Translate("esMX", "rhapsody-shindigger", {
	title = "Rhapsody Shindigger",
	subtitle = "Antiguo jinete de grifo de Pico Nidal",
	found = "Campamento Machacacanillas",
	hint = [=[Busque al antiguo jinete de grifo que elabora su propia bebida al este de Pico Nidal.]=],
	allegiance = "Clan Martillo Salvaje (despedido)",
	aliases = { "Rhapsody" },
	sections = {
		{
			title = "Resumen",
			text = [=[Rhapsody Shindigger fue en otro tiempo el mejor jinete de grifo de {link:aerie-peak}Pico Nidal{/link}. Voló con el explorador {link:brohann-caskbelly}Brohann Caskbelly{/link} sobre el {link:swamp-of-sorrows}Pantano de las Penas{/link} en busca de un templo ahogado. Tras aquel vuelo se dio a la bebida, y el aviario prescindió de él. Ahora tiene su propio campamento de elaboración, y tiene hipo en cada frase.]=],
		},
		{
			title = "Importancia",
			text = [=[Solo Rhapsody conocía la verdad que {link:brohann-caskbelly}Brohann{/link} buscaba. El templo de los Atal'ai yace bajo el pantano, y él lo había visto con sus propios ojos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Se bebió un barril entero de cerveza negra antes del vuelo sobre el pantano.
• Cayó de su grifo al agua, fue arrastrado al fondo y se encontró entre trols en un templo hundido.
• Escapó con un fragmento de una tablilla Atal'ai.]=],
		},
	},
	chapters = {
		{
			title = "Un trago fuerte",
			hint = [=[Lleve al antiguo jinete lo que necesita para contar su historia.]=],
			text = [=[Rhapsody no quería hablar del pantano estando sobrio. Solo una bebida elaborada con mollejas e hígados de bestias de la lejana {link:kalimdor}Kalimdor{/link} podía soltarle la lengua. Entonces, por fin, salió la historia. El jinete había caído al pantano, se había hundido hasta el templo de los {link:temple-of-atal-hakkar}Atal'ai{/link} y había salido nadando con una reliquia trol en la mano. El templo que {link:brohann-caskbelly}Brohann{/link} buscaba era real.]=],
		},
	},
	mentions = {
		{ text = "Rhapsody Shindigger" },
		{ text = "El cóctel de {link:kalimdor}Kalimdor{/link} de Rhapsody" },
		{ text = "La historia de Rhapsody" },
	},
	bonds = {
		{ id = "gryphon-master-talonaxe", name = "Maestro de grifos Talonaxe", note = "lo despidió" },
		{ id = "brohann-caskbelly", name = "Brohann Caskbelly", note = "voló con él sobre el pantano" },
		{ id = "gilveradin-sunchaser", name = "Gilveradin Sunchaser", note = "comparte su campamento" },
	},
})

