	hint = [=[Busque al sacerdote proscrito que vive entre los Secacorteza cerca de Shadra'Alor.]=],
	allegiance = "Ninguna (desterrado de los Atal'ai)",
	sections = {
		{
			title = "Resumen",
			text = [=[El exiliado Atal'ai fue en otro tiempo sacerdote de los Atal'ai, la secta trol del templo ahogado del {link:swamp-of-sorrows}Pantano de las Penas{/link}. Cuando el profeta {link:jammal-an-the-prophet}Jammal'an{/link} predijo que la invocación de {link:hakkar}Hakkar{/link} haría inmortales a los Atal'ai, este sacerdote pidió prudencia. Por ello fue tachado de infiel y expulsado. La sentencia de su pueblo lo envió al norte a vivir entre los {link:witherbark-trolls}Secacorteza{/link}, un destino que los Atal'ai consideran peor que la muerte.]=],
		},
		{
			title = "Importancia",
			text = [=[El exiliado es una rara voz de duda dentro del culto de {link:hakkar}Hakkar{/link}. Cree que la profecía de {link:jammal-an-the-prophet}Jammal'an{/link} destruirá a su pueblo, y conoce los ritos de invocación lo bastante bien como para temerlos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Advirtió a {link:jammal-an-the-prophet}Jammal'an{/link} que la profecía podía no ser más que una manipulación.
• Juzgó inofensivos los objetos Atal'ai que le trajeron del pantano, pero advirtió de lo que el ritual podría hacer si se completaba.
• Busca venganza por su exilio.]=],
		},
	},
	chapters = {
		{
			title = "La cabeza del profeta",
			hint = "Vengue al exiliado en el profeta que lo expulsó.",
			text = [=[El exiliado quería la cabeza de {link:jammal-an-the-prophet}Jammal'an{/link}. Esperaba que su pueblo quedara libre una vez desaparecido el profeta, y poder volver a casa. Cuando se cumplió la hazaña, dio las gracias, y lloró. Las falsas visiones de Jammal'an ya habían llevado a los Atal'ai a su perdición. No le quedaba un hogar al que volver.]=],
		},
	},
	mentions = {
		{ text = "El exiliado Atal'ai" },
		{ text = "Regreso junto a Fel'Zerul" },
		{ text = "{link:jammal-an-the-prophet}Jammal'an el Profeta{/link}" },
	},
	bonds = {
		{ id = "fel-zerul", name = "Fel'Zerul", note = "le envió los objetos Atal'ai" },
	},
})

