Translate("esMX", "vile-priestess-hexx", {
	title = "Sacerdotisa vil Hexx",
	subtitle = "Suma sacerdotisa de los Vilrama",
	found = "La cima de Jintha'Alor",
	hint = [=[Enfréntese a la suma sacerdotisa que domina la cima de Jintha'Alor.]=],
	allegiance = "Trols Vilrama",
	aliases = { "Hexx" },
	sections = {
		{
			title = "Resumen",
			text = [=[La sacerdotisa vil Hexx es la suma sacerdotisa de los trols {red:vilebranch-trolls}Vilrama{/red}. Domina la cima de {link:jintha-alor}Jintha'Alor{/link} con su guardia de élite Aman'zasi. Sus tejidos oscuros llenan recipientes de sangre corrupta por toda la ciudad, y a través de ellos el poder del dios de la sangre, {link:hakkar}Hakkar{/link}, empuja a su pueblo a una ferocidad demente e inmortal.]=],
		},
		{
			title = "Importancia",
			text = [=[Hexx es la razón por la que los Vilrama son algo más que una tribu salvaje. Gracias a ella se han convertido en siervos de {link:hakkar}Hakkar{/link}, y toman cautivos de todos los pueblos de {link:the-hinterlands}las Tierras del Interior{/link} para sacrificarlos. {link:dwarves}Enanos{/link} y trols por igual sufren su dominio. Tanto {link:aerie-peak}Pico Nidal{/link} como el {link:revantusk-village}Poblado Sañadiente{/link} han puesto precio a su cabeza. Los Sañadiente advierten que, aunque caiga, otra se alzará en su lugar.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Preparó al anciano {link:primal-torntusk}Torntusk{/link} de los {link:revantusk-village}Sañadiente{/link} para sacrificarlo a {link:hakkar}Hakkar{/link}.
