			title = "Resumen",
			text = [=[Shadra es la diosa araña de los trols {link:witherbark-trolls}Secacorteza{/link}. La llaman la Reina del Veneno, y de ella procede el veneno más potente que conocen. No camina entre sus adoradores. Solo acude cuando se lee en voz alta su verdadero nombre ante su altar de {link:shadra-alor}Shadra'Alor{/link}, y ese nombre está tan cargado de poder que los sabios solo lo pronuncian en susurros.]=],
		},
		{
			title = "Importancia",
			text = [=[Shadra es el corazón de la fe de los {link:witherbark-trolls}Secacorteza{/link}. Su nombre se escribió hace mucho en una tablilla de la ciudad trol de {red:zul-farrak}Zul'Farrak{/red}, al otro lado del mar. La {link:royal-apothecary-society}Real Sociedad de Boticarios{/link} de los {link:forsaken}Renegados{/link} codicia su veneno por encima de cualquier otro.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Da su veneno a los {link:witherbark-trolls}Secacorteza{/link}, que lo guardan en botellas en sus poblados.
• Fue invocada ante su altar con un hechizo de invocación hecho por el {link:master-gadrin}maestro Gadrin{/link} de los {link:darkspear-trolls}Lanza Negra{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La Reina del Veneno",
			hint = "Invoque a la diosa araña en Shadra'Alor.",
			text = [=[El {link:apothecary-lydon}boticario Lydon{/link}, de {link:tarren-mill}Molino Tarren{/link}, quería el veneno más fresco de los {link:witherbark-trolls}Secacorteza{/link}, y ninguna araña común servía. El maestro Gadrin sabía de dónde procedía. De una tablilla de Zul'Farrak salió su verdadero nombre, y de Gadrin salió un pergamino que podía llamarla. Ante el altar de {link:shadra-alor}Shadra'Alor{/link} se leyeron las palabras, y la Reina del Veneno respondió. Su veneno fue a Molino Tarren, y de allí al {link:the-apothecarium}Apothecarium{/link} de {link:undercity}Entrañas{/link}.]=],
