})

Translate("esMX", "primal-torntusk", {
	title = "Primal Torntusk",
	subtitle = "Líder del Poblado Sañadiente",
	found = "Poblado Sañadiente",
	hint = "Hable con la trol que manda en el Poblado Sañadiente.",
	allegiance = "Trols Sañadiente · Horda",
	aliases = { "Torntusk" },
	sections = {
		{
			title = "Resumen",
			text = [=[Primal Torntusk manda en el {link:revantusk-village}Poblado Sañadiente{/link}. Sus órdenes salen con su propio nombre, y sus recompensas se anuncian a la vista de todos. Es una guerrera de los {red:revantusk-trolls}Sañadiente{/red} y una sabia de su pueblo, y conoce las artes oscuras de los Vilrama lo bastante bien como para deshacerlas. Cuando los Vilrama llegaron de noche y se llevaron a su compañero, no se desesperó. Pidió ayuda y fue a la guerra.]=],
		},
		{
			title = "Importancia",
			text = [=[Torntusk sostiene el punto de apoyo de la {link:horde}Horda{/link} en {link:the-hinterlands}las Tierras del Interior{/link}. Su poblado es pequeño y está rodeado de enemigos: los Vilrama al norte y al oeste, las bestias salvajes de las colinas y los Martillo Salvaje al otro lado de esta tierra. Bajo su mando, los {link:revantusk-village}Sañadiente{/link} se han convertido en el enemigo más tenaz de los Vilrama. Solo ella, entre los suyos, parece entender que el verdadero enemigo no es la tribu sino el dios al que sirve.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reunió a su poblado después de que un asalto Vilrama se llevara a su compañero y a su capitán de la guardia.
• Purificó los recipientes de sangre corrupta sacados de {link:jintha-alor}Jintha'Alor{/link}.
• Puso precio a la cabeza de la sacerdotisa vil {link:vile-priestess-hexx}Hexx{/link} y de su guardia Aman'zasi.
• Busca un nuevo capitán de la guardia que sustituya al caído Malkhor.]=],
		},
	},
	chapters = {
		{
			title = "El asalto de medianoche",
			hint = [=[Rescate de Jintha'Alor al compañero de la líder de Sañadiente.]=],
			text = [=[Los Vilrama llegaron en mitad de la noche y se llevaron vivo al anciano Torntusk. Los espías {link:revantusk-village}Sañadiente{/link} averiguaron que lo retenían en lo alto de {link:jintha-alor}Jintha'Alor{/link} y que {link:vile-priestess-hexx}Hexx{/link} pretendía ofrecérselo a {link:hakkar}Hakkar{/link}. Torntusk dijo claramente que su poblado no podría soportar semejante pérdida. Los grilletes se rompieron, el anciano volvió a casa y la deuda de los Sañadiente fue grande.]=],
		},
		{
			title = "Aflojar la garra",
			hint = [=[Robe los recipientes corruptos de Jintha'Alor para Primal Torntusk.]=],
			text = [=[Torntusk comprendió que los Vilrama no luchaban con su propia fuerza. La sangre de sus recipientes portaba el poder del dios sin rostro, y los enloquecía. Cuando le llevaron los recipientes, extrajo de ellos la corrupción. La garra del {link:hakkar}dios de la sangre{/link} se aflojó. Advirtió a su pueblo que solo sería por un tiempo.]=],
		},
		{
			title = "Un capitán para Sañadiente",
			hint = [=[Demuestre que es digno de la capitanía de la guardia Sañadiente.]=],
			text = [=[Con Malkhor muerto, el puesto de capitán de la guardia quedó vacío. Torntusk hizo un llamamiento a cualquiera que quisiera diezmar las filas de guerreros, cazadores de las sombras, bebedores de sangre y devoradores de almas de los Vilrama. Quienes respondieron recibieron agradecimiento y recompensa. La elección en sí, dijo, esperaría hasta el año siguiente.]=],
		},
	},
	mentions = {
		{ text = "¡El anciano Torntusk secuestrado!" },
		{ text = "Regreso junto a Primal Torntusk" },
		{ text = "Recipientes oscuros" },
		{
			text = [=[Se busca: la sacerdotisa vil {link:vile-priestess-hexx}Hexx{/link} y sus esbirros]=],
		},
		{
			text = [=[Puesto vacante: capitán de la guardia del {link:revantusk-village}Poblado Sañadiente{/link}]=],
		},
	},
	bonds = {
		{ id = "elder-torntusk", name = "Anciano Torntusk", note = "su compañero" },
		{ id = "huntsman-markhor", name = "Montero Markhor", note = "hermano de su capitán caído" },
		{ id = "vile-priestess-hexx", name = "Sacerdotisa vil Hexx", note = "su enemiga" },
		{ id = "falstad-wildhammer", name = "Falstad Wildhammer", note = "thane de los enanos a los que odia su pueblo" },
	},
})

